SELECT DISTINCT countries.CountryId, countries.CountryName 
FROM countries 
JOIN car_makers ON countries.CountryId = car_makers.Country;

SELECT d.name FROM Dogs d 
WHERE d.owner_id NOT IN (
    SELECT t.dog_id FROM Treatments t 
    GROUP BY t.dog_id 
    HAVING SUM(t.cost_of_treatment) > 1000
);

SELECT c.Code FROM country c 
WHERE c.Code NOT IN (SELECT cl.CountryCode FROM countrylanguage cl WHERE cl.Language = 'English') 
AND c.GovernmentForm NOT LIKE '%Republic%';
